import React, { useState } from 'react';
import styled from 'styled-components'; // styled-components를 활용해서 더 예쁘게 꾸며줄 거야! 💅

// 탭 전체 섹션 스타일
const TabContentSection = styled.div`
  padding: 30px;
  background-color: #ffffff;
  border-radius: 12px;
  box-shadow: 0 6px 20px rgba(0, 0, 0, 0.08);
  margin-bottom: 25px;
  transition: all 0.3s ease-in-out;

  &:hover {
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.12);
  }
`;

// 탭 제목 스타일
const TabContentTitle = styled.h3`
  font-size: 26px;
  color: #333d4b;
  margin-bottom: 30px;
  font-weight: bold;
  text-align: center;
  position: relative;

  &::after {
    content: '';
    display: block;
    width: 60px;
    height: 4px;
    background-color: #6a67f1;
    margin: 15px auto 0;
    border-radius: 2px;
  }
`;

// 정보 항목 스타일
const InfoItem = styled.div`
  display: flex;
  align-items: center;
  padding: 15px 0;
  border-bottom: 1px dashed #e0e0e0;
  &:last-child {
    border-bottom: none;
  }
`;

// 정보 라벨 스타일
const InfoLabel = styled.span`
  font-weight: bold;
  color: #555;
  width: 120px;
  flex-shrink: 0;
  font-size: 17px;
`;

// 정보 값 스타일
const InfoValue = styled.span`
  color: #333d4b;
  font-size: 17px;
  flex-grow: 1;
  word-break: break-all;
`;

// 입력 필드 스타일
const InfoValueInput = styled.input`
  flex-grow: 1;
  padding: 12px 15px;
  border: 1px solid #ced4da;
  border-radius: 8px;
  font-size: 16px;
  color: #495057;
  transition: all 0.3s ease;

  &:focus {
    border-color: #6a67f1;
    box-shadow: 0 0 0 3px rgba(106, 103, 241, 0.2);
    outline: none;
  }
`;

// 버튼 스타일
const ActionButton = styled.button`
  background-color: #6a67f1;
  color: white;
  padding: 13px 25px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  font-size: 17px;
  font-weight: bold;
  transition: background-color 0.3s ease, transform 0.2s ease;

  &:hover {
    background-color: #5350e0;
    transform: translateY(-2px);
  }

  &:active {
    transform: translateY(0);
  }

  &.secondary {
    background-color: #6c757d;
    &:hover {
      background-color: #5a6268;
    }
  }

  &.delete-button {
    background-color: #dc3545;
    &:hover {
      background-color: #c82333;
    }
  }
`;

// 버튼 그룹 스타일
const ButtonGroup = styled.div`
  display: flex;
  justify-content: center;
  gap: 15px;
  margin-top: 40px;
`;

const AccountInfoTab = ({ adminInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState(adminInfo);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // 실제 백엔드 관리자 계정 정보 수정 API 호출 로직
    alert('관리자 계정 정보가 성공적으로 수정되었습니다! 🥳 (API 연동 필요)');
    console.log('수정된 관리자 정보:', formData);
    setIsEditing(false);
  };

  return (
    <TabContentSection className="account-info-tab">
      <TabContentTitle>계정 정보 {!isEditing ? '보기' : '수정'}</TabContentTitle>

      {!isEditing ? (
        <>
          <InfoItem>
            <InfoLabel>이름</InfoLabel>
            <InfoValue>{adminInfo.name}</InfoValue>
          </InfoItem>
          <InfoItem>
            <InfoLabel>이메일</InfoLabel>
            <InfoValue>{adminInfo.email}</InfoValue>
          </InfoItem>
          <InfoItem>
            <InfoLabel>역할</InfoLabel>
            <InfoValue>{adminInfo.role}</InfoValue>
          </InfoItem>
          <InfoItem>
            <InfoLabel>마지막 로그인</InfoLabel>
            <InfoValue>{adminInfo.lastLogin}</InfoValue>
          </InfoItem>
          <ButtonGroup>
            <ActionButton onClick={() => setIsEditing(true)}>정보 수정 ✏️</ActionButton>
          </ButtonGroup>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          <InfoItem>
            <InfoLabel htmlFor="adminName">이름</InfoLabel>
            <InfoValueInput
              type="text"
              id="adminName"
              name="name"
              value={formData.name}
              onChange={handleChange}
              required
            />
          </InfoItem>
          <InfoItem>
            <InfoLabel htmlFor="adminEmail">이메일</InfoLabel>
            <InfoValueInput
              type="email"
              id="adminEmail"
              name="email"
              value={formData.email}
              onChange={handleChange}
              required
            />
          </InfoItem>
          {/* 비밀번호 변경 등 추가 필드는 필요하면 이 곳에 넣어줘! */}
          <ButtonGroup>
            <ActionButton type="submit">저장 ✅</ActionButton>
            <ActionButton type="button" className="secondary" onClick={() => setIsEditing(false)}>취소 ↩️</ActionButton>
          </ButtonGroup>
        </form>
      )}
    </TabContentSection>
  );
};

export default AccountInfoTab;
